<script setup lang="ts">
definePageMeta({middleware:'admin'})
const db=useSupabaseClient()
const requests=ref<any[]>([]),notes=ref<Record<string,string>>({}),logoUrls=ref<Record<string,string>>({}),busy=ref(''),error=ref(''),message=ref('')
async function load(){
 const r=await db.from('school_requests').select('id,school_name,school_domain,school_code,contact_name,contact_email,contact_position,contact_phone,notes,logo_path,status,created_at,review_notes').order('created_at',{ascending:false})
 requests.value=r.data||[];error.value=r.error?.message||'';logoUrls.value={}
 for(const request of requests.value){if(!request.logo_path)continue;const result=await db.storage.from('school-logos').createSignedUrl(request.logo_path,3600);if(result.data?.signedUrl)logoUrls.value[request.id]=result.data.signedUrl}
}
onMounted(load)
async function review(r:any,approve:boolean){error.value='';message.value='';if(!confirm(`${approve?'APPROVE':'REJECT'} ${r.school_name} and ${approve?'assign school administrator access to':'decline'} ${r.contact_email}? Verify the school and representative independently first.`))return;busy.value=r.id;const result=await db.rpc('review_school_request',{p_request_id:r.id,p_approve:approve,p_review_notes:notes.value[r.id]||null});busy.value='';if(result.error){error.value=result.error.message;return}message.value=approve?'School created with its logo, domain disabled pending verification, and administrator assigned.':'Request rejected.';await load()}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/dashboard">← Dashboard</NuxtLink><h1>School Requests</h1><p>Verify the school, email domain and representative's authority independently before approval.</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success">{{message}}</p><div v-for="r in requests" :key="r.id" class="card"><h2>{{r.school_name}} <small>({{r.status}})</small></h2><img v-if="logoUrls[r.id]" :src="logoUrls[r.id]" :alt="`${r.school_name} logo`" style="max-width:180px;max-height:140px;object-fit:contain"/><p>Domain: @{{r.school_domain}} · Code: {{r.school_code||'—'}}</p><p>Proposed administrator: {{r.contact_name}} ({{r.contact_position}})</p><p>Email: {{r.contact_email}} · Phone: {{r.contact_phone||'—'}}</p><p v-if="r.notes">Notes: {{r.notes}}</p><p v-if="r.review_notes">Review: {{r.review_notes}}</p><template v-if="r.status==='pending'"><label>Review notes<textarea v-model="notes[r.id]" rows="2"></textarea></label><div class="actions"><button class="btn" :disabled="!!busy" @click="review(r,true)">Approve & Create School</button><button class="btn" :disabled="!!busy" @click="review(r,false)">Reject</button></div></template></div><p v-if="!requests.length">No school requests yet.</p></div></div></template>
